import { describe, test, expect } from 'vitest';
import { getMaxOrderQuantity } from './maxOrderQuantity';

const baseProduct = { id: 'product-1', name: 'Natura Mini Dress' };

describe('getMaxOrderQuantity', () => {
  test('returns c_maxOrderQuantity when present and a valid positive number', () => {
    expect(getMaxOrderQuantity({ ...baseProduct, c_maxOrderQuantity: 5 })).toBe(5);
  });

  test('falls back to 3 when c_maxOrderQuantity is absent', () => {
    expect(getMaxOrderQuantity({ ...baseProduct })).toBe(3);
  });

  test('falls back to 3 when c_maxOrderQuantity is 0', () => {
    expect(getMaxOrderQuantity({ ...baseProduct, c_maxOrderQuantity: 0 })).toBe(3);
  });

  test('falls back to 3 when c_maxOrderQuantity is negative', () => {
    expect(getMaxOrderQuantity({ ...baseProduct, c_maxOrderQuantity: -1 })).toBe(3);
  });

  test('falls back to 3 when c_maxOrderQuantity is non-numeric (e.g. a misconfigured string value)', () => {
    expect(getMaxOrderQuantity({ ...baseProduct, c_maxOrderQuantity: '5' })).toBe(3);
  });

  // Mutation-tested gap (zm-tester, SFCC-11 step 3.4): removing Number.isFinite(value) from the
  // implementation let this exact case through uncaught - typeof Infinity === 'number' is true,
  // so a bare `typeof value === 'number' && value > 0` check alone would accept it.
  test('falls back to 3 when c_maxOrderQuantity is Infinity (a number, but not a usable cap)', () => {
    expect(getMaxOrderQuantity({ ...baseProduct, c_maxOrderQuantity: Infinity })).toBe(3);
  });
});

import type { ShopperBasketsTypes, ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { findImageGroupBy } from '@salesforce/retail-react-app/app/utils/image-groups-utils';
import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';

/*
 * Converts an SDK basket `productItem` into a self-contained display-data shape, mirroring the
 * `productListCardMapper.ts` precedent (`overrides/app/pages/product-list/productListCardMapper.ts`,
 * PR #85) for how a page-scoped SDK-to-props mapper is organised in this codebase: exported
 * "select"-prefixed functions (that file exports three: `selectGalleryImages`,
 * `selectSizeChipValues`, `selectProductListCard` - corrected here, an earlier draft of this
 * comment said "a single" one, which was wrong), an untyped-base-package input narrowed to a
 * local type, and a `.test.ts` asserting the mapped shape directly (see that file's own
 * `ProductListSearchHit`/`RawImage` pattern, mirrored below for `CartLineItem`/`CartItemImage`).
 *
 * Disclosed design choice, not a directly sourced requirement (flagged per this step's own
 * instructions): `ProductItem`/`ItemVariantProvider` (`overrides/app/components/product-item/
 * index.tsx:140`, `overrides/app/components/item-variant/index.tsx:43`) both currently declare
 * their real data-carrying prop as the raw untyped basket/product object itself
 * (`product`/`variant`, both `SfccProduct`/`SfccVariant = any`) — today's leaves read every
 * display field (image, name, combined attributes) directly off that object via
 * `useItemVariant()`, not from individually-mapped props. This mapper is, per this step's plan
 * text, "an as-yet-unused-by-anything-else container-layer function" — it does not change or
 * feed either of those two files (out of this step's scope). What it produces instead is a pure,
 * tested equivalent of the specific per-field computations those leaves and
 * `product-quantity-picker.tsx`/`use-derived-product.js` already perform internally off that same
 * raw object (image+alt, combined colour/size, quantity, stepQuantity) — ready for whichever
 * future step decides how a real page hands data down, without having modified any of those
 * existing files.
 *
 * `CartLineItem` models the REAL runtime shape a basket line item has by the time it reaches
 * those leaves: the un-overridden base cart page never passes the raw `basket.productItems[i]`
 * alone — it merges it with the matching full `Product` (fetched separately via `useProducts`)
 * before handing it down: `product={{...productItem, ...productsByItemId[productItem.itemId],
 * price: productItem.price, quantity: ...}}` (see
 * `node_modules/@salesforce/retail-react-app/app/components/product-item-list/index.jsx`, the
 * `<ProductItem product={...}>` call). `imageGroups`/`variationAttributes`/`variationValues`/
 * `stepQuantity`/`name` all come from that merged-in `Product` half, not from
 * `ShopperBasketsTypes.ProductItem` itself (confirmed against its generated fields — it has no
 * image/variation/stepQuantity fields at all beyond its own `{[key: string]: any}` catch-all).
 *
 * Both halves are `Pick`'d, not intersected raw (zm-tester, SFCC-11 step 3.4 finding): the real
 * generated `ProductItem` type carries the identical `{[key: string]: any}` catch-all the comment
 * above already calls out on `Product`. Intersecting it raw would silently resolve a typo'd field
 * name (or a nonexistent one) to `any` instead of a compile error — empirically confirmed harmless
 * today (every real access below is spelled correctly) but a real, latent gap a future edit could
 * hit silently. `Pick`ing both halves closes it the same way on both sides.
 */
type CartLineItem = Pick<ShopperBasketsTypes.ProductItem, 'itemId' | 'productId' | 'quantity' | 'productName'> &
  Pick<
    ShopperProductsTypes.Product,
    'imageGroups' | 'variationAttributes' | 'variationValues' | 'stepQuantity' | 'name'
  >;

type CartItemImage = {
  src?: string;
  /**
   * Always a string, never undefined — even when there's no image at all (falls back to the
   * item's own name, then `''`). See `selectCartItemImage`'s own doc comment for the fallback
   * chain and why this differs from `productListCardMapper.ts`'s `toCardImage`, which returns
   * `undefined` for the whole image on a miss instead.
   */
  alt: string;
};

type CartItemMapperResult = {
  itemId?: string;
  productId?: string;
  name: string;
  image: CartItemImage;
  combinedAttributes: string;
  quantity?: number;
  stepQuantity: number;
};

/**
 * Matches `node_modules/@salesforce/retail-react-app/app/hooks/use-derived-product.js:38`'s own
 * `product?.stepQuantity || 1` exactly — reused as a value, not a shared import, since that hook
 * itself isn't a pure function this module can call (it's stateful, `useState`-backed).
 */
const DEFAULT_STEP_QUANTITY = 1;

/**
 * Selects this line item's display image, always returning a defined `alt` even when there is no
 * image at all (unlike `productListCardMapper.ts`'s `toCardImage`, which returns `undefined` for
 * the whole image on a miss — a PLP card can legitimately skip rendering entirely when it has
 * nothing to show; a cart line item cannot, per this step's own pass criteria).
 *
 * The lookup itself reuses `findImageGroupBy` exactly as
 * `overrides/app/components/item-variant/item-image.tsx:70-73` already does (same `viewType:
 * 'small'` / `selectedVariationAttributes` call) rather than reimplementing image-group matching.
 */
const selectCartItemImage = (item: CartLineItem): CartItemImage => {
  const image = findImageGroupBy(item.imageGroups, {
    viewType: 'small',
    selectedVariationAttributes: item.variationValues,
  })?.images?.[0];

  return {
    src: image?.disBaseLink || image?.link,
    alt: image?.alt || item.productName || item.name || '',
  };
};

/**
 * Combines the colour and size variation values into the single string the Figma cart-item spec
 * calls for, reusing the exact mechanism
 * `overrides/app/components/item-variant/item-attributes.tsx:98,148-150` already uses for its own
 * `combineAttributeValues` behaviour (`getDisplayVariationValues(...)` then
 * `Object.values(...).join(', ')`) rather than reimplementing string-combining from scratch.
 *
 * Ordering is inherited from that same call, not independently re-sorted here: it reflects
 * whichever order the incoming `variationValues` object's own keys are in (see
 * `getDisplayVariationValues`'s `Object.entries(values).reduce(...)`,
 * `node_modules/@salesforce/retail-react-app/app/utils/product-utils.js:30`). This is the
 * identical mechanism `item-attributes.tsx`'s own docblock (line 31) already cites as producing
 * "Lilac Sand, One size" (colour, size) for real Zimmermann catalog data —
 * `product-item/index.tsx`'s docblock (line 44) corroborates the same combined-string behaviour
 * generically ("colour, size") without repeating that specific example. This function inherits
 * that already-verified behaviour rather than re-guaranteeing the order independently.
 */
const selectCombinedAttributes = (item: CartLineItem): string => {
  const variationValues = getDisplayVariationValues(item.variationAttributes, item.variationValues);
  return variationValues ? Object.values(variationValues).join(', ') : '';
};

/**
 * Maps one basket line item (already merged with its full product data — see this file's own
 * module docblock) to a plain display-data shape: image, name, one combined colour/size string,
 * and quantity/stepQuantity passed through. Pure function, no hooks — keeps every consumer in B3
 * prop-driven with no data-fetching hook in a leaf, per this step's own plan text.
 */
export const selectCartItemProps = (item: CartLineItem): CartItemMapperResult => ({
  itemId: item.itemId,
  productId: item.productId,
  name: item.productName || item.name || '',
  image: selectCartItemImage(item),
  combinedAttributes: selectCombinedAttributes(item),
  quantity: item.quantity,
  stepQuantity: item.stepQuantity || DEFAULT_STEP_QUANTITY,
});

