import { describe, test, expect } from 'vitest';
import { selectCartItemProps } from './cartItemMapper';

const fullLineItem = {
  itemId: 'item-1',
  productId: 'product-1',
  productName: 'Natura Mini Dress',
  quantity: 2,
  stepQuantity: 1,
  imageGroups: [
    {
      viewType: 'small',
      images: [{ link: 'https://example.com/small.jpg', alt: 'Natura Mini Dress' }],
    },
  ],
  variationAttributes: [
    { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand' }] },
    { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One size' }] },
  ],
  variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
};

describe('selectCartItemProps', () => {
  test('maps a full line item to all props', () => {
    expect(selectCartItemProps(fullLineItem)).toEqual({
      itemId: 'item-1',
      productId: 'product-1',
      name: 'Natura Mini Dress',
      image: { src: 'https://example.com/small.jpg', alt: 'Natura Mini Dress' },
      combinedAttributes: 'Lilac Sand, One size',
      quantity: 2,
      stepQuantity: 1,
    });
  });

  test('does not crash and still returns a defined alt when the item has no image', () => {
    const itemWithNoImage = {
      itemId: 'item-2',
      productId: 'product-2',
      productName: 'Zahara Top',
      quantity: 1,
    };

    const result = selectCartItemProps(itemWithNoImage);

    expect(result.image.src).toBeUndefined();
    expect(result.image.alt).toBe('Zahara Top');
  });

  // Regression coverage for the documented combine order: colour then size, matching the real
  // example item-attributes.tsx's own docblock (line 31) already cites ("Lilac Sand, One size")
  // for this exact mechanism against real Zimmermann catalog data.
  test('combines colour and size into one string in the documented order', () => {
    const item = {
      itemId: 'item-3',
      productName: 'Aphrodite Midi Dress',
      variationAttributes: [
        { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand' }] },
        { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One size' }] },
      ],
      variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
    };

    expect(selectCartItemProps(item).combinedAttributes).toBe('Lilac Sand, One size');
  });

  test('passes quantity and stepQuantity through from the line item', () => {
    const item = {
      itemId: 'item-4',
      productName: 'Halcyon Blazer',
      quantity: 3,
      stepQuantity: 2,
    };

    const result = selectCartItemProps(item);

    expect(result.quantity).toBe(3);
    expect(result.stepQuantity).toBe(2);
  });

  // Mutation-tested gap (zm-tester, SFCC-11 step 3.4): every other fixture in this file either
  // omits stepQuantity without asserting on it, or supplies a truthy value - neither shape can
  // catch the DEFAULT_STEP_QUANTITY fallback being dropped entirely. Matches
  // use-derived-product.js:38's own `product?.stepQuantity || 1` precedent this function mirrors.
  test('falls back to stepQuantity 1 when the line item has none', () => {
    const item = {
      itemId: 'item-5',
      productName: 'Solstice Skirt',
      quantity: 1,
    };

    expect(selectCartItemProps(item).stepQuantity).toBe(1);
  });
});

